import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public class Solution {
    static final Object AUSENTE = new Object();

    static class MiniMongo {
        private final Map<String, Map<String, Object>> documentos = new LinkedHashMap<>();

        void inserir(Map<String, Object> documento) {
            if (documento == null) throw new IllegalArgumentException("documento nulo");
            Object id = documento.get("_id");
            if (!(id instanceof String s) || s.isBlank()) {
                throw new IllegalArgumentException("_id String obrigatorio");
            }
            if (documentos.containsKey(s)) {
                throw new IllegalStateException("_id duplicado: " + s);
            }
            documentos.put(s, copiarMapa(documento));
        }

        Map<String, Object> buscarPorId(String id) {
            var doc = documentos.get(id);
            return doc == null ? null : copiarMapa(doc);
        }

        List<Map<String, Object>> buscar(Map<String, Object> filtro) {
            if (filtro == null) throw new IllegalArgumentException("filtro nulo");
            var out = new ArrayList<Map<String, Object>>();
            documentos.values().stream()
                .filter(d -> corresponde(d, filtro))
                .sorted((a, b) -> ((String) a.get("_id")).compareTo((String) b.get("_id")))
                .forEach(d -> out.add(copiarMapa(d)));
            return out;
        }

        boolean atualizarUm(String id, Map<String, Object> atualizacao) {
            if (!(atualizacao != null && atualizacao.get("$set") instanceof Map<?, ?> set)) {
                throw new IllegalArgumentException("use {\"$set\": {...}}");
            }
            var doc = documentos.get(id);
            if (doc == null) return false;
            for (var e : set.entrySet()) {
                doc.put((String) e.getKey(), copiarValor(e.getValue()));
            }
            return true;
        }

        int remover(Map<String, Object> filtro) {
            var ids = new ArrayList<String>();
            for (var doc : documentos.values()) {
                if (corresponde(doc, filtro)) ids.add((String) doc.get("_id"));
            }
            ids.forEach(documentos::remove);
            return ids.size();
        }

        int total() { return documentos.size(); }

        @SuppressWarnings("unchecked")
        private static Map<String, Object> copiarMapa(Map<String, Object> origem) {
            var copia = new LinkedHashMap<String, Object>();
            for (var e : origem.entrySet()) copia.put(e.getKey(), copiarValor(e.getValue()));
            return copia;
        }

        @SuppressWarnings("unchecked")
        private static Object copiarValor(Object valor) {
            if (valor instanceof Map<?, ?> m) {
                var copia = new LinkedHashMap<String, Object>();
                for (var e : m.entrySet()) copia.put((String) e.getKey(), copiarValor(e.getValue()));
                return copia;
            }
            if (valor instanceof List<?> l) {
                var copia = new ArrayList<Object>();
                for (var item : l) copia.add(copiarValor(item));
                return copia;
            }
            return valor;
        }

        private static boolean corresponde(Map<String, Object> doc, Map<String, Object> filtro) {
            for (var e : filtro.entrySet()) {
                if (!avaliar(extrair(doc, e.getKey()), e.getValue())) return false;
            }
            return true;
        }

        private static Object extrair(Map<String, Object> doc, String caminho) {
            Object atual = doc;
            int inicio = 0;
            while (inicio <= caminho.length()) {
                int ponto = caminho.indexOf('.', inicio);
                String parte = ponto < 0 ? caminho.substring(inicio) : caminho.substring(inicio, ponto);
                if (!(atual instanceof Map<?, ?> m)) return AUSENTE;
                if (!m.containsKey(parte)) return AUSENTE;
                atual = m.get(parte);
                if (ponto < 0) return atual;
                inicio = ponto + 1;
            }
            return atual;
        }

        private static boolean avaliar(Object atual, Object esperado) {
            if (esperado instanceof Map<?, ?> ops) {
                for (var e : ops.entrySet()) {
                    String op = (String) e.getKey();
                    Object arg = e.getValue();
                    if (!aplicar(op, atual, arg)) return false;
                }
                return true;
            }
            return igual(atual, esperado);
        }

        private static boolean aplicar(String op, Object atual, Object arg) {
            return switch (op) {
                case "$eq" -> igual(atual, arg);
                case "$ne" -> !igual(atual, arg);
                case "$gt" -> compara(atual, arg) > 0;
                case "$gte" -> compara(atual, arg) >= 0;
                case "$lt" -> compara(atual, arg) < 0;
                case "$lte" -> compara(atual, arg) <= 0;
                case "$in" -> {
                    if (!(arg instanceof List<?> lista)) {
                        throw new IllegalArgumentException("$in exige lista");
                    }
                    boolean achou = false;
                    for (var item : lista) if (igual(atual, item)) achou = true;
                    yield achou;
                }
                case "$exists" -> {
                    if (!(arg instanceof Boolean quer)) {
                        throw new IllegalArgumentException("$exists exige boolean");
                    }
                    yield (atual != AUSENTE) == quer;
                }
                default -> throw new IllegalArgumentException("operador nao suportado: " + op);
            };
        }

        private static boolean igual(Object atual, Object esperado) {
            if (esperado == null) return atual == AUSENTE || atual == null;
            if (atual == AUSENTE) return false;
            return Objects.equals(atual, esperado);
        }

        private static int compara(Object atual, Object arg) {
            if (!(atual instanceof Number a) || !(arg instanceof Number b)) {
                throw new IllegalArgumentException("comparacao exige numeros");
            }
            return Double.compare(a.doubleValue(), b.doubleValue());
        }
    }
}

