import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.Map;

class SolutionTest {
    private Solution.MiniMongo novaColecao() {
        var m = new Solution.MiniMongo();
        m.inserir(Map.of("_id", "p1", "total", 120,
            "status", "PAGO", "endereco", Map.of("cidade", "Recife")));
        m.inserir(Map.of("_id", "p2", "total", 80,
            "status", "CRIADO", "endereco", Map.of("cidade", "Sao Paulo")));
        var p3 = new java.util.HashMap<String, Object>();
        p3.put("_id", "p3");
        p3.put("total", 200);
        p3.put("status", "PAGO");
        p3.put("endereco", Map.of("cidade", "Recife"));
        p3.put("cupom", null);
        m.inserir(p3);
        return m;
    }

    @Test void insercaoEBuscaPorId() {
        var m = novaColecao();
        assertEquals(3, m.total());
        assertEquals(120, m.buscarPorId("p1").get("total"));
        assertNull(m.buscarPorId("nada"));
    }

    @Test void idDuplicadoFalha() {
        var m = novaColecao();
        assertThrows(IllegalStateException.class, () -> m.inserir(Map.of("_id", "p1")));
        assertThrows(IllegalArgumentException.class, () -> m.inserir(Map.of("total", 1)));
    }

    @Test void igualdadeECaminhoAninhado() {
        var m = novaColecao();
        assertEquals(List.of("p1", "p3"), ids(m.buscar(Map.of("endereco.cidade", "Recife"))));
        assertEquals(List.of("p2"), ids(m.buscar(Map.of("status", "CRIADO"))));
    }

    @Test void operadoresDeComparacaoEIn() {
        var m = novaColecao();
        assertEquals(List.of("p1", "p3"), ids(m.buscar(Map.of("total", Map.of("$gte", 100)))));
        assertEquals(List.of("p1", "p2"), ids(m.buscar(Map.of("total", Map.of("$lt", 200)))));
        assertEquals(List.of("p1", "p3"), ids(m.buscar(Map.of(
            "status", Map.of("$in", List.of("PAGO", "ENVIADO"))))));
    }

    @Test void existsEDistincaoEntreNuloEAusente() {
        var m = novaColecao();
        assertEquals(List.of("p3"), ids(m.buscar(Map.of("cupom", Map.of("$exists", true)))));
        assertEquals(List.of("p1", "p2"), ids(m.buscar(Map.of("cupom", Map.of("$exists", false)))));
        assertEquals(List.of("p1", "p2", "p3"), ids(m.buscar(java.util.Collections.singletonMap("cupom", null))));
    }

    @Test void atualizacaoComSet() {
        var m = novaColecao();
        assertTrue(m.atualizarUm("p1", Map.of("$set", Map.of("status", "ENVIADO"))));
        assertFalse(m.atualizarUm("nada", Map.of("$set", Map.of("status", "X"))));
        assertEquals("ENVIADO", m.buscarPorId("p1").get("status"));
        assertThrows(IllegalArgumentException.class, () -> m.atualizarUm("p1", Map.of("status", "X")));
    }

    @Test void remocaoPorFiltro() {
        var m = novaColecao();
        assertEquals(2, m.remover(Map.of("status", "PAGO")));
        assertEquals(1, m.total());
        assertEquals(0, m.remover(Map.of("status", "PAGO")));
    }

    @Test void copiaProfundaNaEntradaESaida() {
        var m = new Solution.MiniMongo();
        var endereco = new java.util.HashMap<String, Object>(Map.of("cidade", "Recife"));
        var doc = new java.util.HashMap<String, Object>(Map.of("_id", "x", "endereco", endereco));
        m.inserir(doc);
        endereco.put("cidade", "Mudou");
        assertEquals("Recife", ((Map<?, ?>) m.buscarPorId("x").get("endereco")).get("cidade"));
        @SuppressWarnings("unchecked")
        var devolvido = (Map<String, Object>) m.buscarPorId("x").get("endereco");
        devolvido.put("cidade", "Hack");
        assertEquals("Recife", ((Map<?, ?>) m.buscarPorId("x").get("endereco")).get("cidade"));
    }

    private List<String> ids(List<Map<String, Object>> docs) {
        return docs.stream().map(d -> (String) d.get("_id")).toList();
    }
}
